; Build options (written by build.sh)
OPT_TALL equ 1                  ; (always: the tables that sit in the program rather than at the top of memory)
CAR_U    equ 15                 ; draw_car: the car frame's x - 12 for the big cars, 15 for the small
OPT_OBJ  equ 0                 ; 1: the coloured objects (obj_paint, objects.asm)
OPT_MUSIC equ 0                ; 1: the ditty in the race
OPT_PIT  equ 0                 ; 1: the crew chief talks under the window (off: the logo is there)
OPT_AY   equ 0                 ; 1: the race tune on the AY sound chip (AY=1 bash build.sh; off since 15 Nov 2026: Grant, "Lets not use the AY chip for now please - old spectrum sounds")
OPT_BRIDGE equ 0               ; 1: the track has a bridge (TRACK=5 bash build.sh: levels, walls, ramps - bridge.asm)
OPT_LOOP equ 0                 ; 1: the screen copy as a loop of one character row (LOOP=1 bash build.sh)
OPT_TOWERF equ 0               ; 1: the race order draws its cars from their frames (TOWER=1 bash build.sh)
OPT_MULTI equ 0                ; 1: several tracks in one load (tools/make_multi.py sets it: not for build.sh alone)
OPT_FLIP equ 0                 ; 1: draw_car and the title car read such a frame last row first (FLIP=1 bash build.sh)
OPT_TILE1 equ 0                ; 1: one tile routine (TILE1=1 bash build.sh)
OPT_PACEFIX equ 0              ; 1: pace_gate counts pictures (PACEFIX=1 bash build.sh)
OPT_AI equ 0                   ; the computer cars: 0 as they were, 1 NORMAL, 2 HARD (AI=1 bash build.sh; ai_tune.asm)
OPT_ROADCOL equ 7              ; the trial road paper: 7 white, 6 yellow (ROADCOL=6 ROADW=1 bash build.sh)
OPT_ROADBR equ 0               ; 1: the trial road paper bright (ROADCOL=5 ROADBR=1 ROADW=1 bash build.sh: bright cyan)
OPT_ROADW equ 0                ; 1: the road white (ROADW=1 bash build.sh); 2: and plain, no dots (ROADW=2) - a trial
OPT_CNOS equ 0                 ; 1: the chasers' NOS (CNOS=1 bash build.sh)
OPT_OIL equ 0                  ; 1: the oil spills (OIL=1 bash build.sh)
OPT_MAPHUD equ 0               ; 1: the mini-map on the panel (MAPHUD=1 bash build.sh)
OPT_JFACE equ 0                ; 1: the faces move with the music (JFACE=1 bash build.sh)
OPT_LJ equ 0                   ; 1: the finish line judges the places (LINEJ=1 bash build.sh)
OPT_LAPFIX equ 0               ; 1: your lap is not lost when the game loses your waypoint (LAPFIX=1 bash build.sh)
OPT_QMUL equ 0                 ; 1: qmul by shift and add (QMUL=1 bash build.sh)
OPT_UPPER equ 0                ; 1: tables above the looped copy routine (UPPER=1 LOOP=1 bash build.sh)
OPT_SIMPLE equ 0               ; 1: group C - your car on the card model, one bump rule (SIMPLE=1 bash build.sh)
OPT_TANKUP equ 0               ; 1: the tank weaker early, stronger each lap (TANKUP=1 bash build.sh)
OPT_PICK equ 0                 ; 1: choose your car at the title (PICK=1 bash build.sh)
OPT_GRIPX equ 0                ; 1: harder slides, a wider grip scale (GRIPX=1 bash build.sh)
OPT_MAP40 equ 0                ; 1: the mini-map 40 wide, its ink in the program (MAPW40=1 bash build.sh)
OPT_RT equ 0                   ; 1: the race track trial - black road, green grass (RACETRACK=1 bash build.sh)
OPT_CHOOSE equ 0               ; 1: the choose screen (tools/build_choose.sh: not for build.sh alone)
OPT_GRIP1 equ 0                ; 1: your car moved, and its grip worked out, once a picture (GRIP1=1 bash build.sh)
OPT_2P equ 0                   ; 1: two players in one view (TWOP=1 RACETRACK=1 bash build.sh)
OPT_GRIDBACK equ 0             ; 1: you start last on the grid (race-track builds; GRID_BACK=0 bash build.sh for pole)
OPT_GRIDPLACE equ 0            ; GRID_PLACE=1..5: your place on the grid (0: pole, or last with GRID_BACK)
GRID_ORD macro
        db 0,1,4,3,2
        endm
OPT_2PPTS equ 0                ; two players, the POINTS rule: first to this many points (0: the LEASH rule; TWOP_PTS=3)
OPT_REACT1 equ 0               ; 1: the computer cars decide every 8th TV frame, not every 4th (REACT1=1 bash build.sh)
OPT_RTPUP equ 0                ; RACETRACK: 1 - the place plate is drawn from the program, not from under 0x8000 (tracks 1 and 2)
OPT_ARROWC equ 1               ; RACETRACK: 1 - the corner arrow black over grass, green beside it (option C; not track 3)
OPT_FACESLOW equ 0             ; RACETRACK: 1 - the drivers' looks under 0x8000, Grant's newest (not track 3, not the plain game)
OPT_RTBAND equ 0               ; RACETRACK: 1 - a pair of the same banded picture is copied as it is (rt_sq: rt_c1; 87 bytes - track 3 has not the room)
OPT_RTLAP equ 0                ; RACETRACK: 1 - off the track and back on further round costs no lap (src/lap_low.asm; not track 3)
OPT_RTEYES equ 0               ; RACETRACK: 1 - the race order's faces look left and right until the lights go green (not track 3)
OPT_RTROWS equ 19              ; the race track trial: how many of the window's 19 rows of squares scroll (RT_ROWS=16 RACETRACK=1 bash build.sh)
OPT_CARDS equ 0                ; 1: the driver cards - each car its own speed, acceleration and grip (CARDS=1; tools/build_cards.sh)
OPT_ARMOUR equ 0               ; 1: armour, the bar on the HUD and the two weapons (ARMOUR=1 CARDS=1; tools/build_armour.sh)
OPT_RACE equ 0                 ; 1: the title offers RACE or COMBAT (RACEMODE=1 ARMOUR=1: tools/build_race.sh)
RT_SMOOTHN equ 0               ; the track's centre line smoothed this many times (RT_SMOOTH: the round-turn track - ai_tune.asm balances its cars)
OPT_SCRUB equ 0                ; 0: as before; n: a slide costs speed - yours 1/2^n of it a TV frame, a computer car twice the drag (SCRUB=n)
OPT_CLOTHPLAIN equ 0           ; 1: the tablecloth one plain colour, no dots (CLOTHPLAIN=1: quicker)
OPT_NOSTURN equ 0              ; 1: on NOS you steer half as fast, and while you steer no NOS push or top speed (NOSTURN=1)
OPT_WEIGHT equ 0               ; 1: bumps and damage by the cars' weights (WEIGHT=1: the breakfast race tape; needs ARMOUR=1 MUG=1)
OPT_FLASHME equ 0              ; 1: your car flashes on the grid until the lights go green (FLASHME=1)
OPT_MUG equ 0                  ; 1: the coffee mug - your damage - on an ARMOUR tape (MUG=1: the breakfast table race tape)
OPT_NOSBOX equ 0               ; 1: the NOS you hold shown as a canister in a rounded box, one colour square each (NOSBOX=1)
OPT_RACEONLY equ 0             ; 1: RACE only - no COMBAT, every car its own picture and driver card (RACEONLY=1 RACEMODE=1)
OPT_HEAD32 equ 0               ; 1: the racer drawn at 32 headings (2, HEAD32=all: every car), the computer cars pushed 32 ways
OPT_MIRROR equ 0               ; 1: a computer car's heading that is another's frame mirrored is not kept (MIRROR=1, with FLIP=1; 2, MIRROR=all: yours too)
OPT_STEADY equ 0               ; 0: as before; 5: every picture 5 TV frames and the game moved 5 frames a picture (STEADY=5)
OPT_ELASTIC equ 0              ; 1: RACE mode - a computer car behind the leader gets a small push (ELASTIC=1 RACEMODE=1)
GAME_SPEED equ 100             ; the whole game's speed, percent of today's (GAME_SPEED=60 CARDS=1: tools/build_slow.sh)
OPT_NOS equ 0                  ; NOS: 0 twice the push and top speed; 1 a half more; 2 a quarter more (NOS=1 bash build.sh)
NOS_FR equ 50                  ; NOS: how many TV frames one canister burns (NOS_FR=100 bash build.sh)
